const cases = $input.all();

function enforceCRM(record) {
  const { source, decision: inputDecision } = record;

  if (
    !source ||
    typeof source.prospect_id !== "string" ||
    !source.prospect_id.trim() ||
    !source.crm ||
    typeof source.crm !== "object" ||
    Array.isArray(source.crm)
  ) {
    throw new Error("MISSING_SOURCE_DATA");
  }

  if (
    !inputDecision ||
    typeof inputDecision !== "object" ||
    Array.isArray(inputDecision)
  ) {
    throw new Error("MISSING_DECISION");
  }

  const crm = source.crm;

  const booleanFields = [
    "do_not_contact",
    "open_opportunity",
    "existing_customer",
    "existing_relationship_or_owner",
    "previous_disqualification"
  ];

  for (const field of booleanFields) {
    if (typeof crm[field] !== "boolean") {
      throw new Error(`INVALID_CRM_BOOLEAN:${field}`);
    }
  }

  if (
    typeof crm.last_contacted_days_ago !== "number" ||
    !Number.isFinite(crm.last_contacted_days_ago) ||
    crm.last_contacted_days_ago < 0
  ) {
    throw new Error("INVALID_LAST_CONTACT");
  }

  if (inputDecision.prospect_id !== source.prospect_id) {
    throw new Error("PROSPECT_ID_MISMATCH");
  }

  const decision = { ...inputDecision };

  const validReasons = [
    "NONE",
    "DO_NOT_CONTACT",
    "OPEN_OPPORTUNITY",
    "EXISTING_CUSTOMER",
    "EXISTING_RELATIONSHIP_OR_OWNER",
    "PREVIOUS_DISQUALIFICATION",
    "RECENT_CONTACT",
    "OTHER"
  ];

  if (
    typeof decision.suppression_applied !== "boolean" ||
    !validReasons.includes(decision.suppression_reason)
  ) {
    throw new Error("INVALID_AI_SUPPRESSION");
  }

  const aiHold =
    decision.outreach_disposition === "HOLD";

  // Reject contradictory AI suppression states.
  if (
    aiHold !== decision.suppression_applied ||
    (aiHold && decision.suppression_reason === "NONE") ||
    (!aiHold && decision.suppression_reason !== "NONE")
  ) {
    throw new Error("INCONSISTENT_AI_SUPPRESSION");
  }

  const aiReason = aiHold
    ? decision.suppression_reason
    : "NONE";

  const reasons = [];

  // Deterministic CRM restrictions.
  // Order establishes primary-reason precedence.
  if (crm.do_not_contact) {
    reasons.push("DO_NOT_CONTACT");
  }

  if (crm.open_opportunity) {
    reasons.push("OPEN_OPPORTUNITY");
  }

  if (crm.existing_customer) {
    reasons.push("EXISTING_CUSTOMER");
  }

  if (crm.existing_relationship_or_owner) {
    reasons.push("EXISTING_RELATIONSHIP_OR_OWNER");
  }

  if (crm.previous_disqualification) {
    reasons.push("PREVIOUS_DISQUALIFICATION");
  }

  if (crm.last_contacted_days_ago <= 14) {
    reasons.push("RECENT_CONTACT");
  }

  const crmHold = reasons.length > 0;

  decision.ai_suppression_reason = aiReason;

  // CRM governance and AI judgement remain distinct.
  decision.crm_policy_status = crmHold
    ? "SUPPRESSED"
    : "CLEAR";

  decision.crm_policy_reasons = reasons;

  if (crmHold && aiHold) {
    decision.suppression_source = "BOTH";
  } else if (crmHold) {
    decision.suppression_source = "CRM";
  } else if (aiHold) {
    decision.suppression_source = "AI";
  } else {
    decision.suppression_source = "NONE";
  }

  decision.review_required = aiHold && !crmHold;

  // CRM restrictions always override permission to contact.
  if (crmHold) {
    decision.suppression_applied = true;
    decision.suppression_reason = reasons[0];
    decision.outreach_disposition = "HOLD";

    decision.decision_summary =
      "Outreach on hold due to CRM restriction: " +
      reasons.join(", ") + ".";

    decision.decision_rationale =
      (decision.decision_rationale || "") +
      "\nINDEPENDENT CRM ENFORCEMENT: " +
      reasons.join(", ") +
      ". CRM restrictions override the AI recommendation." +
      (aiHold
        ? "\nAI also recommended HOLD: " + aiReason + "."
        : "");

  } else if (aiHold) {
    // Preserve conservative AI decisions.
    // Do not claim they were independently verified by CRM.
    decision.suppression_applied = true;
    decision.suppression_reason = aiReason;
    decision.outreach_disposition = "HOLD";

    decision.decision_summary =
      "AI recommended holding outbound pending review. " +
      "Reason: " + aiReason + ".";

    decision.decision_rationale =
      (decision.decision_rationale || "") +
      "\nAI-INITIATED HOLD: " + aiReason +
      ". No corresponding deterministic CRM restriction " +
      "was found. Review is required before releasing outbound.";
  }

  decision.crm_policy_checked_at = new Date().toISOString();

  return decision;
}

// Preserve individual record outcomes for batch processing.
return cases.map((item, index) => {
  const record = item.json;

  try {
    return {
      json: {
        test_id: record.test_id ?? null,
        test_name: record.test_name ?? null,
        expected: record.expected ?? null,
        execution_status: "PROCESSED",
        actual: enforceCRM(record),
        error_code: null
      },
      pairedItem: { item: index }
    };
  } catch (error) {
    return {
      json: {
        test_id: record.test_id ?? null,
        test_name: record.test_name ?? null,
        expected: record.expected ?? null,
        execution_status: "REJECTED",
        actual: null,
        error_code: error.message
      },
      pairedItem: { item: index }
    };
  }
});
